from binascii import unhexlify

data = (
    "50a9caf6c63795a712420f0cb93ef3b7aebcc970ffe6"
    "7ff234249284ac69838d0c3c00006ecbc2b6cd6cdc46"
    "e22c97b084487bebcd6231ccefe3c2f7cb56f488941f"
    "863a1c47"
)

def decode_data(data):
    try:
        decoded = unhexlify(data)
        print("Decoded data (ASCII):", decoded.decode('utf-8', 'ignore'))
    except Exception as e:
        print("Error during decoding:", e)

if __name__ == "__main__":
    decode_data(data)
